reproductionHarness:
import { test, expect, vi } from "bun:test";
import { heapStats } from "bun:jsc";
import * as fs from "node:fs/promises";
import * as path from "node:path";
import type { AssistantMessage } from "@oh-my-pi/pi-ai";
import { AssistantMessageEventStream } from "@oh-my-pi/pi-ai/utils/event-stream";
import { isRecord, ptree } from "@oh-my-pi/pi-utils";
import type { AgentSession } from "../src/session/agent-session";
import { initTheme } from "@oh-my-pi/pi-tui/theme";
import { Settings, resetSettingsForTest } from "../src/config/settings";
import { cfgClaudeResetsAutoRedeem, cfgCodexResetsAutoRedeem } from "../src/session/settings";
import { AgentRegistry } from "../src/registry/agent-registry";
import { startSubagentSurfaces } from "../src/rex-panes";
import { InteractiveMode } from "../src/modes/interactive-mode";
import { ExtensionUiController } from "../src/modes/controllers/extension-ui-controller";
import { EventBus } from "../src/utils/event-bus";
import { createInteractiveModeContext, createPaneSessionFixture } from "../test/helpers/interactive-mode-context";
import { VirtualTerminal } from "../../tui/test/virtual-terminal";
import { buildPaneRelay, resetPaneRelay } from "../scripts/pane-relay";
import { summarizeSnapshot, type SnapshotSummary } from "./snapshot";
import { Composer } from "@oh-my-pi/pi-tui/prompt/composer";

const receiptDir = path.join(import.meta.dir, "receipts", process.env.WIRE_MEMORY_RECEIPT_RUN ?? (process.env.WIRE_MEMORY_SNAPSHOTS === "1" ? "diagnostic" : "acceptance"));
const mib = 1024 * 1024;
const diagnostic = process.env.WIRE_MEMORY_SNAPSHOTS === "1";
const snapshotCycles = new Set([10, 15]);
const correctedMain = process.env.WIRE_MEMORY_MAIN === "1";
const plateau = process.env.WIRE_MEMORY_PLATEAU === "1";
const cycleCount = plateau ? 15 : 5;
const receiptPrefix = plateau ? "plateau" : correctedMain ? "corrected" : diagnostic ? "diagnostic" : "";

interface Sample {
	at: string;
	cycle: number;
	phase: "baseline" | "open" | "closed" | "settled";
	rss: number;
	heapUsed: number;
	heapTotal: number;
	external: number;
	heapSize: number;
	heapCapacity: number;
	extraMemorySize: number;
	objectCount: number;
	closedTreesAlive: number;
	closedTreesSeen: number;
	sessionObjectsAlive: number;
	sessionObjectsSeen: number;
	objectTypeCounts: Record<string, number>;
}

async function command(argv: string[]): Promise<string> {
	const child = Bun.spawn(argv, { stdout: "pipe", stderr: "pipe" });
	const timeout = setTimeout(() => child.kill(), 10_000);
	try {
		const [stdout, stderr, code] = await Promise.all([
			new Response(child.stdout).text(), new Response(child.stderr).text(), child.exited,
		]);
		if (code !== 0) throw new Error(`${argv[0]} ${argv[1]} failed (${code}): ${stderr}`);
		return stdout;
	} finally {
		clearTimeout(timeout);
	}
}

interface Group { session_id: string; label: string }
async function groups(): Promise<Group[]> {
	const parsed: unknown = JSON.parse(await command(["rex", "--autostart=false", "ls", "--json"]));
	if (!isRecord(parsed) || !Array.isArray(parsed.sessions)) throw new Error("Malformed Rex session list");
	return parsed.sessions.filter((session): session is Group => isRecord(session) && typeof session.session_id === "string" && typeof session.label === "string" && session.label.startsWith("omp: HeapCycle"));
}

async function runCycle(cycle: number, bus: EventBus, clearCapturedContexts: () => void): Promise<string> {
	const registry = AgentRegistry.global();
	const fixtures: Array<ReturnFixture> = [];
	const runs: Promise<unknown>[] = [];
	const ids: string[] = [];
	const eventUnsubscribers: Array<() => void> = [];
	let groupId: string | undefined;
	try {
		for (const letter of ["A", "B", "C"]) {
			const id = `HeapCycle${cycle}${letter}`;
			const fixture = createPaneSessionFixture();
			cfgCodexResetsAutoRedeem.override(fixture.session.settings, "no");
			cfgClaudeResetsAutoRedeem.override(fixture.session.settings, "no");
			for (const target of [fixture.session, fixture.session.agent, fixture.session.modelRegistry, fixture.session.modelRegistry.authStorage, fixture.stream]) sessionObjects.push(new WeakRef(target));
			fixtures.push(fixture);
			ids.push(id);
			registry.register({ id, displayName: id, kind: "sub", parentId: "main", session: fixture.session });
			bus.emit("task:subagent:lifecycle", { id, agent: "fake", agentSource: "project", description: "Deterministic heap workload", index: ids.length - 1, status: "started", parentToolCallId: `heap-cycle-${cycle}` });
			if (correctedMain) eventUnsubscribers.push(fixture.session.subscribe(event => bus.emit("task:subagent:event", { id, event })));
			runs.push(fixture.session.prompt("Render the deterministic memory workload"));
			fixture.partial.content = [{ type: "text", text: "" }];
			fixture.stream.push({ type: "start", partial: fixture.partial });
			fixture.stream.push({ type: "text_start", contentIndex: 0, partial: fixture.partial });
		}
		for (let attempt = 0; attempt < 100; attempt++) {
			const group = (await groups()).find(group => group.label.startsWith(`omp: HeapCycle${cycle}`));
			if (group) {
				const inspect: unknown = JSON.parse(await command(["rex", "--autostart=false", "session", "inspect", group.session_id, "--json"]));
				if (!isRecord(inspect) || !Array.isArray(inspect.windows)) throw new Error("Malformed Rex group");
				let blocks = 0;
				for (const window of inspect.windows) {
					if (!isRecord(window) || !Array.isArray(window.layers)) continue;
					for (const layer of window.layers) if (isRecord(layer) && Array.isArray(layer.blocks)) blocks += layer.blocks.length;
				}
				if (blocks === 3) { groupId = group.session_id; break; }
			}
			await Bun.sleep(100);
		}
		if (!groupId) throw new Error(`Cycle ${cycle} did not open three real panes`);
		let content = "";
		for (let frame = 0; frame < 30; frame++) {
			const delta = `Memory frame ${frame}: deterministic streaming text and renderer workload.\n`;
			content += delta;
			for (const fixture of fixtures) {
				fixture.partial.content = [{ type: "text", text: content }];
				fixture.stream.push({ type: "text_delta", contentIndex: 0, delta, partial: fixture.partial });
			}
			await Bun.sleep(50);
		}
		await sample("open", cycle);
		return groupId;
	} finally {
		for (const id of ids) {
			if (correctedMain) bus.emit("task:subagent:lifecycle", { id, agent: "fake", agentSource: "project", description: "Deterministic heap workload", index: ids.indexOf(id), status: "aborted", parentToolCallId: `heap-cycle-${cycle}` });
			registry.detachSession(id);
			registry.setStatus(id, "parked");
			registry.unregister(id);
		}
		for (const fixture of fixtures) fixture.finish();
		await Promise.allSettled(runs);
		for (const fixture of fixtures) await fixture.close();
		for (const unsubscribe of eventUnsubscribers) unsubscribe();
		fixtures.length = 0;
		runs.length = 0;
		for (let attempt = 0; attempt < 100 && groupId; attempt++) {
			if (!(await groups()).some(group => group.session_id === groupId)) break;
			await Bun.sleep(100);
		}
		if (groupId && (await groups()).some(group => group.session_id === groupId)) throw new Error(`Cycle ${cycle} group did not close`);
		clearCapturedContexts();
	}
}

interface ReturnFixture {
	session: AgentSession;
	partial: AssistantMessage;
	stream: AssistantMessageEventStream;
	finish(): void;
	close(): Promise<void>;
}
const closedTrees: WeakRef<object>[] = [];
const sessionObjects: WeakRef<object>[] = [];
const rows: Sample[] = [];
let output: fs.FileHandle;

async function sample(phase: Sample["phase"], cycle: number): Promise<Sample> {
	const rss = Number((await command(["ps", "-o", "rss=", "-p", String(process.pid)])).trim()) * 1024;
	const usage = process.memoryUsage();
	const stats = heapStats();
	const row: Sample = {
		at: new Date().toISOString(), cycle, phase, rss,
		heapUsed: usage.heapUsed, heapTotal: usage.heapTotal, external: usage.external,
		heapSize: stats.heapSize, heapCapacity: stats.heapCapacity, extraMemorySize: stats.extraMemorySize,
		objectCount: stats.objectCount,
		closedTreesAlive: closedTrees.filter(reference => reference.deref() !== undefined).length,
		closedTreesSeen: closedTrees.length,
		sessionObjectsAlive: sessionObjects.filter(reference => reference.deref() !== undefined).length,
		sessionObjectsSeen: sessionObjects.length,
		objectTypeCounts: Object.fromEntries(Object.entries(stats.objectTypeCounts).filter(([name]) => /InteractiveMode|SocketTerminal|Pane|Terminal|AgentSession|Composer|Container|Map|Promise|Array|Function|Object|String|string/.test(name))),
	};
	rows.push(row);
	await output.appendFile(`${JSON.stringify(row)}\n`);
	console.log(JSON.stringify({ phase, cycle, rssMiB: rss / mib, heapUsedMiB: row.heapUsed / mib, heapSizeMiB: row.heapSize / mib, closedTreesAlive: row.closedTreesAlive, closedTreesSeen: row.closedTreesSeen }));
	return row;
}

test("real three-pane cycles with fake streaming and no forced garbage collection", async () => {
	const activeSettings = await Settings.init({ inMemory: true });
	cfgCodexResetsAutoRedeem.override(activeSettings, "no");
	cfgClaudeResetsAutoRedeem.override(activeSettings, "no");
	await initTheme();
	const fetchSpy = vi.spyOn(globalThis, "fetch").mockRejectedValue(new Error("Network is disabled in the pane memory harness"));
	const dispose = InteractiveMode.prototype.disposeEmbedded;
	const capture = vi.spyOn(InteractiveMode.prototype, "disposeEmbedded").mockImplementation(function (this: InteractiveMode) {
		closedTrees.push(new WeakRef(this), new WeakRef(this.ui));
		dispose.call(this);
	});
	const relayPath = path.resolve(import.meta.dir, "../src/rex-panes/relay/omp-pane-relay.bin");
	await fs.mkdir(receiptDir, { recursive: true });
	output = await fs.open(path.join(receiptDir, receiptPrefix ? `${receiptPrefix}-cycles.jsonl` : "cycles.jsonl"), "w", 0o600);
	await buildPaneRelay(relayPath);
	const bus = new EventBus();
	let surfaces: { dispose(): Promise<void> } | undefined;
	let main: InteractiveMode | undefined;
	let mainFixture: ReturnFixture | undefined;
	try {
		if (correctedMain) {
			mainFixture = createPaneSessionFixture();
			cfgCodexResetsAutoRedeem.override(mainFixture.session.settings, "no");
			cfgClaudeResetsAutoRedeem.override(mainFixture.session.settings, "no");
			main = new InteractiveMode(mainFixture.session, "fake-memory-main", undefined, undefined, undefined, undefined, bus, new Composer({ terminal: new VirtualTerminal(80, 24), preferences: { quiet: true } }), bus);
			await main.init({ suppressWelcomeIntro: true });
			const warm = mainFixture.session.prompt("Warm the fake main renderer before measuring pane deltas");
			mainFixture.partial.content = [{ type: "text", text: "" }];
			mainFixture.stream.push({ type: "start", partial: mainFixture.partial });
			mainFixture.stream.push({ type: "text_start", contentIndex: 0, partial: mainFixture.partial });
			let text = "";
			for (let frame = 0; frame < 30; frame++) {
				const delta = `Memory frame ${frame}: deterministic streaming text and renderer workload.\n`;
				text += delta;
				mainFixture.partial.content = [{ type: "text", text }];
				mainFixture.stream.push({ type: "text_delta", contentIndex: 0, delta, partial: mainFixture.partial });
				await Bun.sleep(50);
			}
			mainFixture.finish();
			await Promise.allSettled([warm]);
			main.ui.renderNow();
		} else {
			const ui = new ExtensionUiController(createInteractiveModeContext()).createToolUIContext();
			surfaces = startSubagentSurfaces({ settings: activeSettings, subagentEventBus: bus, toolUi: ui, mainTerminal: new VirtualTerminal() });
		}
		// Real idle time is the measurement condition; fake time cannot settle OS/JSC memory.
		await Bun.sleep(60_000);
		const baseline = await sample("baseline", 0);
		const snapshots: SnapshotSummary[] = [];
		for (let cycle = 1; cycle <= cycleCount; cycle++) {
			const groupId = await runCycle(cycle, bus, () => capture.mockClear());
			await output.appendFile(`${JSON.stringify({ event: "group_closed", cycle, groupId, at: new Date().toISOString() })}\n`);
			await sample("closed", cycle);
			await Bun.sleep(60_000);
			await sample("settled", cycle);
			if (diagnostic && snapshotCycles.has(cycle)) {
				Bun.gc(true);
				await Bun.sleep(0);
				Bun.gc(true);
				const snapshot = summarizeSnapshot(`cycle-${cycle}`);
				snapshots.push(snapshot);
				await Bun.write(path.join(receiptDir, `snapshot-${cycle}.json`), JSON.stringify(snapshot, null, 2));
			}
		}
		const settled = rows.filter(row => row.phase === "settled");
		const summary = {
			baseline, settled, networkFetchCalls: fetchSpy.mock.calls.length,
			cycle5MinusCycle1RssMiB: (settled[4].rss - settled[0].rss) / mib,
			cycle5MinusCycle1HeapUsedMiB: (settled[4].heapUsed - settled[0].heapUsed) / mib,
			cycle5MinusCycle1HeapSizeMiB: (settled[4].heapSize - settled[0].heapSize) / mib,
			cycle5MinusBaselineRssMiB: (settled[4].rss - baseline.rss) / mib,
			cycle5MinusBaselineHeapUsedMiB: (settled[4].heapUsed - baseline.heapUsed) / mib,
			cycle5MinusBaselineHeapSizeMiB: (settled[4].heapSize - baseline.heapSize) / mib,
			...(plateau ? {
				cycle15MinusCycle10RssMiB: (settled[14].rss - settled[9].rss) / mib,
				cycle15MinusCycle10HeapUsedMiB: (settled[14].heapUsed - settled[9].heapUsed) / mib,
				cycle15MinusBaselineRssMiB: (settled[14].rss - baseline.rss) / mib,
				cycle15MinusBaselineHeapUsedMiB: (settled[14].heapUsed - baseline.heapUsed) / mib,
			} : {}),
		};
		await Bun.write(path.join(receiptDir, receiptPrefix ? `${receiptPrefix}-summary.json` : "summary.json"), JSON.stringify(summary, null, 2));
		if (snapshots.length === 2) {
			const before = snapshots[0].classes;
			const after = snapshots[1].classes;
			const diff = Object.keys(after).map(name => ({
				name, countDelta: after[name].count - (before[name]?.count ?? 0),
				byteDelta: after[name].bytes - (before[name]?.bytes ?? 0),
			})).sort((a, b) => b.byteDelta - a.byteDelta);
			await Bun.write(path.join(receiptDir, "snapshot-diff.json"), JSON.stringify({ before: snapshots[0].at, after: snapshots[1].at, diff }, null, 2));
		}
		expect(fetchSpy.mock.calls.length).toBe(0);
		if (plateau && !diagnostic) {
			const last = settled[14];
			expect(last.rss - settled[9].rss).toBeLessThanOrEqual(3 * mib);
			expect(last.heapUsed - settled[9].heapUsed).toBeLessThanOrEqual(3 * mib);
			expect(last.heapUsed - baseline.heapUsed).toBeLessThanOrEqual(3 * mib);
			expect(last.closedTreesAlive).toBe(0);
			expect(last.sessionObjectsAlive).toBe(0);
		}
		console.log(JSON.stringify({ summary: { ...summary, baseline: undefined, settled: undefined } }));
	} finally {
		await main?.suspendRpcSocket();
		main?.stop();
		await mainFixture?.close();
		await surfaces?.dispose();
		bus.clear();
		await output.close();
		await resetPaneRelay();
		vi.restoreAllMocks();
		resetSettingsForTest();
	}
}, 1_200_000);
